test("同じ名前の並びと掘る量なら等しい", () => {
  const a = UnderPointer.create(
    ["label", "card", "home"],
    SelectionDigs.NoDeeper,
  );
  const b = UnderPointer.create(
    ["label", "card", "home"],
    SelectionDigs.NoDeeper,
  );

  expect(UnderPointer.equals(a, b)).toBe(true);
});

test("名前が 1 つ違えば等しくない", () => {
  const a = UnderPointer.create(
    ["label", "card", "home"],
    SelectionDigs.NoDeeper,
  );
  const b = UnderPointer.create(
    ["title", "card", "home"],
    SelectionDigs.NoDeeper,
  );

  expect(UnderPointer.equals(a, b)).toBe(false);
});

test("名前の数が違えば等しくない", () => {
  const a = UnderPointer.create(["card", "home"], SelectionDigs.NoDeeper);
  const b = UnderPointer.create(
    ["card", "home", "extra"],
    SelectionDigs.NoDeeper,
  );

  expect(UnderPointer.equals(a, b)).toBe(false);
});

test("掘る量が違えば等しくない", () => {
  const a = UnderPointer.create(
    ["label", "card", "home"],
    SelectionDigs.NoDeeper,
  );
  const b = UnderPointer.create(
    ["label", "card", "home"],
    SelectionDigs.Deepest,
  );

  expect(UnderPointer.equals(a, b)).toBe(false);
});

test("枠の上で同じポインタの下なら等しい", () => {
  const a = Pointing.create(
    UnderPointer.create(["label", "card", "home"], SelectionDigs.NoDeeper),
  );
  const b = Pointing.create(
    UnderPointer.create(["label", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(Pointing.equals(a, b)).toBe(true);
});

test("枠の上でポインタの下が違えば等しくない", () => {
  const a = Pointing.create(
    UnderPointer.create(["label", "card", "home"], SelectionDigs.NoDeeper),
  );
  const b = Pointing.create(
    UnderPointer.create(["title", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(Pointing.equals(a, b)).toBe(false);
});

test("キャンバスの外と枠の外は等しくない", () => {
  expect(Pointing.equals(Pointing.Outside, Pointing.Nothing)).toBe(false);
});

test("枠の上と枠の外は等しくない", () => {
  const onFrame = Pointing.create(
    UnderPointer.create(["label", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(Pointing.equals(onFrame, Pointing.Nothing)).toBe(false);
});

test("ダブルクリック 1 回では 1 階層だけ内側へ進む", async () => {
  await renderOpenedDocument(SampleDocumentWithDeepBranch);

  await userEvent.dblClick(renderedElement(canvasPane(), "deep-title"));

  expect(currentRowNames(tree())).toEqual(["inner-panel"]);
});

test("⌘ を押しながらクリックすると、押した位置のいちばん内側が選ばれる", async () => {
  await renderOpenedDocument(SampleDocumentWithDeepBranch);

  const user = userEvent.setup();
  await user.keyboard("{Meta>}");
  await user.click(renderedElement(canvasPane(), "deep-title"));
  await user.keyboard("{/Meta}");

  expect(currentRowNames(tree())).toEqual(["deep-title"]);
});

test("キーボードで artboard を活性化するとその artboard だけが候補になる", async () => {
  const onSelect = vi.fn();
  const selection = selectionFromArtboards([
    { name: "home", width: 360, height: 240, children: [] },
  ]);
  renderCanvas({ selection, onSelect });

  screen.getByRole("button", { name: "home" }).focus();
  await userEvent.keyboard("{Enter}");

  expect(onSelect).toHaveBeenCalledWith(
    UnderPointer.create(["home"], SelectionDigs.NoDeeper),
  );
});

test("⌘ も押して選択の内側を指すと、いちばん内側の子孫から選択の内側の縁までの距離が出る", () => {
  // `label`（左右 170〜220・上下 115〜135）から `row` の縁まで
  renderCanvas({ selection: selectionDistanceTree(["row"]) });
  drawSelectionDistanceTree();

  movePointer(drawn("label"), Anywhere, "meta");
  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual(["120", "15", "25", "30"]);
});

test("ダブルクリックで中身まで掘ってから同じところを運ぶと、掘った中身が動く", async () => {
  await renderOpenedDocument(setupDocument());
  await userEvent.dblClick(drawn("label"));

  dragLabelOntoPanel();

  // 掘った選択が掴む側へ届いていなければ、外側の `card` ごと `panel` へ移る
  expect(drawnParentName("label")).toBe("panel");
});

test("キャンバスのノードを右クリックすると、押した枝の入口が選ばれる", async () => {
  await renderOpenedDocument();

  rightClick(drawn("home-title"));

  expect(rightPaneHeading().textContent).toContain("home-title");
});

